-- Shared terminal palette, generated by process.py from templates/colors.lua.
--
-- Import it from another config with:
--   package.path = wezterm.home_dir .. "/.cache/theme/?.lua;" .. package.path
--   local colors = require("colors")
--
-- The ANSI/bright arrays are ready to hand to WezTerm's `colors` config.
local colors = {
  foreground = "#@foreground@",
  background = "#@background@",
  primary = "#@primary@",

  black = "#@black@",
  red = "#@red@",
  green = "#@green@",
  yellow = "#@yellow@",
  blue = "#@blue@",
  magenta = "#@magenta@",
  cyan = "#@cyan@",
  white = "#@white@",

  bright_black = "#@bright_black@",
  bright_red = "#@bright_red@",
  bright_green = "#@bright_green@",
  bright_yellow = "#@bright_yellow@",
  bright_blue = "#@bright_blue@",
  bright_magenta = "#@bright_magenta@",
  bright_cyan = "#@bright_cyan@",
  bright_white = "#@bright_white@",
}

colors.ansi = {
  colors.black,
  colors.red,
  colors.green,
  colors.yellow,
  colors.blue,
  colors.magenta,
  colors.cyan,
  colors.white,
}

colors.brights = {
  colors.bright_black,
  colors.bright_red,
  colors.bright_green,
  colors.bright_yellow,
  colors.bright_blue,
  colors.bright_magenta,
  colors.bright_cyan,
  colors.bright_white,
}

return colors
